Object.assign(LANG.pt.skills,{
model:{name:"Modelagem",about:"Diagramas para alinhar o time antes do código: casos de uso, classes e sequência.",client:"Biblioteca comunitária Casa das Letras",title:"Três pessoas, três sistemas na cabeça",
 story:"Antes de programar os empréstimos, a equipe reuniu Seu Antônio, uma voluntária e um leitor. Cada um descreveu \"o sistema\", e pareciam três produtos diferentes: para um, o livro tinha vários exemplares; para outra, cada exemplar era um livro. Ninguém estava errado; faltava um desenho em comum. Um diagrama simples na parede resolveu em vinte minutos o que três reuniões não tinham resolvido.",
 theory:[["Modelo é uma simplificação com propósito","Um diagrama mostra só o que importa para responder a uma pergunta: quem usa o quê, que dados existem, em que ordem as coisas acontecem. Ele alinha as pessoas antes de o código existir."],
  ["Três visões que se completam","Casos de uso mostram quem faz o quê (visão funcional). O diagrama de classes mostra os conceitos e suas relações (visão estática). O diagrama de sequência mostra a troca de mensagens ao longo do tempo (visão dinâmica)."],
  ["Relações e multiplicidade","Um Livro tem muitos Exemplares; um Exemplar pertence a um único Livro. Anotar 1 e * nas pontas da linha evita o mal-entendido mais caro de um sistema: o do modelo de dados."]]},
qual:{name:"Qualidade",about:"Atributos de qualidade, revisão de código, métricas e dívida técnica.",client:"Time da Ponte",title:"O código que só o Caio entende",
 story:"Caio saiu de férias e o sistema da padaria parou. Bia abriu o código: variáveis chamadas x1 e x2, uma função de 400 linhas, nenhuma pista do porquê das decisões. Ela levou dois dias para corrigir uma linha. O código funcionava, mas só para quem o escreveu. A Ponte decidiu: nenhuma mudança entra na linha principal sem que outra pessoa a leia.",
 theory:[["Qualidade tem vários atributos","Além de funcionar, o software precisa ser legível, testável, seguro, eficiente e fácil de mudar. A norma ISO/IEC 25010 organiza esses atributos; a manutenibilidade é o que mais pesa no custo ao longo dos anos."],
  ["Revisão de código","Outra pessoa lê a mudança antes da integração (pull request). Revisões pequenas e frequentes acham defeitos cedo, espalham conhecimento e evitam que o sistema dependa de uma única cabeça. O alvo é o código, nunca o autor."],
  ["Dívida técnica e medição","Atalhos de hoje cobram juros amanhã: cada mudança fica mais lenta. Métricas como complexidade ciclomática, duplicação e cobertura, colhidas por análise estática, mostram onde a dívida se acumula."]]},
devops:{name:"Entrega contínua",about:"Integração e entrega contínuas, ambientes reprodutíveis e rollback.",client:"Cooperativa de entregas Roda Viva",title:"\"Na minha máquina funciona\"",
 story:"A nova versão do aplicativo rodava perfeitamente no notebook da Bia. No servidor, quebrou: outra versão da linguagem, uma biblioteca faltando, uma configuração esquecida. Publicar era um ritual manual de 23 passos anotados num caderno, feito de madrugada uma vez por mês, sempre com medo. O time quer que publicar vire um não-evento: automático, repetível e reversível.",
 theory:[["Integração contínua (CI)","A cada push, um servidor monta o projeto do zero e roda todos os testes. Se algo quebra, o time fica sabendo em minutos, quando o conserto ainda é barato."],
  ["Entrega contínua (CD)","O mesmo processo automatizado leva o software até a produção: build, testes, empacotamento e publicação. Passo manual vira script, e o que é repetível deixa de dar medo."],
  ["Ambientes iguais e volta rápida","Dependências declaradas em arquivo e ambientes padronizados acabam com o \"na minha máquina funciona\". Publicações pequenas e frequentes, com rollback pronto, reduzem o estrago de cada erro."]]}
});
Object.assign(LANG.pt.items,{
q6:{title:"Triagem de requisitos",prompt:"Classifique cada requisito do sistema do posto de saúde.",bins:["Funcional","Não funcional"],cards:["O paciente recebe um lembrete na véspera da consulta","O sistema fica disponível 99% do tempo","A recepcionista remarca consultas","Os dados dos pacientes são armazenados com criptografia"],hint:"Pergunte a cada cartão: isso é algo que o sistema FAZ ou uma qualidade com que ele faz?",why:"Lembrar e remarcar são comportamentos (funcionais). Disponibilidade e criptografia são qualidades do serviço (não funcionais), e costumam ser esquecidas até virarem problema.",analogy:"No cardápio, os pratos são o funcional. Chegar quente, em vinte minutos e numa cozinha limpa é o não funcional: ninguém pede, todo mundo espera."},
a6:{title:"O ritmo de um sprint",prompt:"Ordene os eventos de um sprint do Scrum.",lines:["Planejamento: o time escolhe o que cabe no sprint","Reuniões diárias acompanham o andamento","Revisão: o incremento é mostrado a quem usa","Retrospectiva: o time melhora o próprio processo"],hint:"Primeiro se decide o que fazer; no fim, olha-se o produto e depois o processo.",why:"O sprint abre com o planejamento, segue com as diárias, mostra o resultado na revisão e fecha com a retrospectiva, que alimenta o próximo ciclo.",analogy:"É como uma viagem: traçar a rota, conferir o mapa todo dia, mostrar as fotos na chegada e combinar o que fazer diferente na próxima."},
g6:{title:"Desfazendo um conflito",prompt:"Ordene os passos para resolver um conflito de merge com segurança.",lines:["Trazer a main atualizada para a sua branch","Abrir os arquivos marcados com conflito","Decidir, trecho a trecho, qual versão fica","Rodar os testes para conferir que nada quebrou","Registrar o commit que conclui a junção"],hint:"O conflito só aparece quando as duas versões se encontram; o commit só vem depois de conferir.",why:"A junção revela os conflitos, a decisão é humana e trecho a trecho, e os testes confirmam que a combinação funciona antes do commit final.",analogy:"Dois editores mexeram no mesmo parágrafo: juntam-se as versões, lê-se com calma, escolhe-se a redação, revisa-se o texto inteiro e só então ele vai para a gráfica."},
t6:{title:"O ciclo do TDD",prompt:"Ordene o ciclo do desenvolvimento guiado por testes.",lines:["Escrever um teste que falha","Escrever o mínimo de código para o teste passar","Rodar todos os testes e ver tudo verde","Refatorar com os testes de proteção"],hint:"Vermelho, verde, refatorar.",why:"O teste vem antes e falha (vermelho), o código mínimo o faz passar (verde) e só então se melhora a estrutura, com a rede de testes por baixo.",analogy:"O alfaiate primeiro marca a medida, depois corta o tecido até servir e só no fim dá o acabamento, conferindo a medida a cada ajuste."},
d6:{title:"Sinais de acoplamento",prompt:"Classifique cada situação observada no sistema da cooperativa.",bins:["Baixo acoplamento","Alto acoplamento"],cards:["O cálculo do frete recebe a tabela de preços por parâmetro","A tela acessa o banco de dados diretamente","A cobrança conversa com os pagamentos por meio de uma interface","Mudar o cadastro obriga a alterar outros seis arquivos"],hint:"Pergunte: se esta parte mudar, quantas outras precisam mudar junto?",why:"Receber dependências de fora e conversar por interfaces isola as partes. Tela falando direto com o banco e mudanças em cascata mostram partes amarradas umas às outras.",analogy:"Aparelhos ligados na tomada trocam-se um a um. Aparelhos com os fios soldados entre si obrigam a desmontar a sala para trocar a televisão."},
m1:{title:"Quem usa e para quê",prompt:"Qual diagrama mostra quem usa o sistema e o que cada pessoa consegue fazer com ele?",opts:["Diagrama de casos de uso","Diagrama de classes","Diagrama de sequência","Diagrama de implantação"],hint:"Procure a visão centrada em pessoas (atores) e objetivos.",why:"Casos de uso ligam atores a objetivos: o leitor empresta, a voluntária cadastra. Classes mostram conceitos; sequência mostra a ordem das mensagens.",analogy:"É o cardápio do restaurante visto do salão: quem pode pedir o quê, sem mostrar a cozinha."},
m2:{title:"Livro e exemplar",prompt:"Como modelar corretamente a relação entre Livro e Exemplar?",opts:["Um Livro tem muitos Exemplares; cada Exemplar é de um único Livro","Um Livro tem exatamente um Exemplar","Muitos Livros para muitos Exemplares","Não há relação: são a mesma coisa"],hint:"A biblioteca tem três cópias de Dom Casmurro. Quantos títulos e quantos objetos físicos?",why:"O título é um só; os objetos na estante são vários. É o exemplar que é emprestado, e não o livro. Errar essa multiplicidade contamina todo o banco de dados.",analogy:"A receita é uma; os bolos feitos a partir dela são muitos. Você come um bolo, não a receita."},
m3:{title:"Estrutura ou comportamento",prompt:"Classifique cada frase: ela pertence a qual visão do modelo?",bins:["Visão estática (classes)","Visão dinâmica (sequência)"],cards:["O Leitor possui nome e telefone","O sistema confere se há exemplar disponível e depois registra o empréstimo","Um Empréstimo se refere a um Exemplar","A devolução dispara o aviso para o próximo da fila de espera"],hint:"Estática descreve o que existe; dinâmica descreve o que acontece, e em que ordem.",why:"Atributos e relações são estrutura e valem o tempo todo. Verificar, registrar e avisar são acontecimentos encadeados no tempo.",analogy:"A planta da casa mostra os cômodos (estática); o roteiro de uma visita mostra por onde a pessoa passa e em que ordem (dinâmica)."},
m4:{title:"A sequência do empréstimo",prompt:"Ordene as mensagens do diagrama de sequência \"emprestar livro\".",lines:["O leitor pede o livro no balcão","A voluntária busca o título no sistema","O sistema confere se há exemplar disponível","O sistema registra o empréstimo e a data de devolução","A voluntária entrega o exemplar ao leitor"],hint:"Cada mensagem só faz sentido depois que a anterior foi respondida.",why:"A sequência parte do ator, passa pela consulta e pela verificação e só registra depois de confirmar a disponibilidade. A entrega física fecha o fluxo.",analogy:"É uma coreografia: cada passo responde ao anterior, e trocar a ordem faz os dançarinos trombarem."},
m5:{title:"Quanto modelar",prompt:"O time quer desenhar as 40 classes do sistema em detalhe antes de escrever a primeira linha de código. Qual é a melhor orientação?",opts:["Modelar o necessário para alinhar o time e a parte de maior risco, e evoluir o modelo junto com o código","Modelar tudo em detalhe antes, para não haver retrabalho","Não modelar nada: o código é a documentação","Cada pessoa desenha o seu modelo e depois junta-se tudo"],hint:"Um modelo vale pelo mal-entendido que evita, não pelo número de caixinhas.",why:"Modelo demais envelhece antes de ser usado; modelo de menos deixa o mal-entendido chegar ao código. O ponto certo é o suficiente para decidir com segurança o próximo passo.",analogy:"Para uma viagem você traça a rota e reserva o primeiro hotel; não decide em que mesa vai almoçar no décimo dia."},
u1:{title:"Dois dias para mudar uma linha",prompt:"Bia levou dois dias para corrigir uma linha no código do Caio. Qual atributo de qualidade está em falta?",opts:["Manutenibilidade","Desempenho","Usabilidade","Portabilidade"],hint:"O programa funcionava para o usuário. Para quem ele não funcionava?",why:"Manutenibilidade é a facilidade de entender, corrigir e evoluir o software. É invisível para o usuário e decisiva para o custo.",analogy:"Um carro pode andar bem e ainda assim exigir desmontar o motor para trocar uma lâmpada. Quem sofre é o mecânico, e a conta chega ao dono."},
u2:{title:"Como comentar numa revisão",prompt:"Qual comentário de revisão de código é o mais útil?",opts:["Este laço percorre a lista duas vezes; dá para juntar num só? Posso ajudar se quiser","Código horrível, refaça","Aprovado (sem ter lido)","Eu teria feito de outro jeito"],hint:"Bom comentário aponta um trecho, explica o motivo e abre conversa.",why:"A revisão eficaz é específica, fala do código e não da pessoa, e propõe um caminho. Aprovar sem ler é pior do que não revisar: cria falsa segurança.",analogy:"O bom revisor de texto circula a frase e sugere outra; não devolve o manuscrito com \"está ruim\" escrito na capa."},
u3:{title:"Pagando ou aumentando a dívida",prompt:"Classifique cada atitude quanto à dívida técnica.",bins:["Paga a dívida","Aumenta a dívida"],cards:["Renomear x1 para total_vendas","Copiar e colar uma função para ganhar tempo","Escrever testes antes de mexer em código antigo","Desligar o aviso do analisador estático para o build passar"],hint:"Pergunte: isso deixa a próxima mudança mais fácil ou mais difícil?",why:"Nomes claros e testes reduzem o custo das próximas mudanças. Duplicação e avisos silenciados escondem problemas que voltam maiores.",analogy:"É o cartão de crédito: parcelar resolve o mês, mas cada parcela empurrada aumenta os juros. Renomear e testar é pagar a fatura."},
u4:{title:"O pull request de 2.000 linhas",prompt:"Chega para revisão uma mudança com 2.000 linhas alteradas. Qual é a melhor conduta?",opts:["Pedir que seja dividida em mudanças menores e independentes","Revisar tudo de uma vez, com pressa","Aprovar confiando no autor","Recusar e não explicar o motivo"],hint:"A atenção de quem revisa cai muito depois de algumas centenas de linhas.",why:"Mudanças pequenas são revisadas com atenção de verdade, integradas mais cedo e revertidas com facilidade. Mudança gigante passa sem ser lida.",analogy:"Ninguém confere uma mudança de casa inteira olhando o caminhão fechado. Caixa por caixa, dá para ver o que quebrou."},
u5:{title:"Onde atacar primeiro",prompt:"Uma função tem complexidade ciclomática 35, nenhuma cobertura de testes e é alterada toda semana. Qual é a prioridade?",opts:["Alta: cobrir com testes e depois dividir em partes menores","Baixa: se funciona, não se mexe","Reescrever o sistema inteiro do zero","Nenhuma: métricas não dizem nada"],hint:"Combine três sinais: muitos caminhos, nenhum teste e mudança frequente.",why:"Risco é complexidade multiplicada por frequência de mudança. Primeiro a rede de testes, depois a refatoração em passos pequenos; reescrever tudo troca um risco conhecido por vários desconhecidos.",analogy:"É o cruzamento sem semáforo por onde passa todo mundo na hora do rush: o perigo não está em ele existir, e sim em quantas vezes por dia alguém o atravessa."},
o1:{title:"O que a CI faz",prompt:"O que a integração contínua faz a cada push?",opts:["Monta o projeto e roda os testes automaticamente, avisando se algo quebrou","Publica em produção sem testar","Faz apenas uma cópia de segurança do código","Apaga as branches antigas"],hint:"Pense num vigia que confere cada mudança assim que ela chega.",why:"A CI constrói o projeto do zero e executa os testes a cada mudança. O valor está na rapidez do aviso: minutos, não semanas.",analogy:"É o detector de metais na porta: confere cada pessoa na entrada, em vez de revistar o prédio inteiro no fim do mês."},
o2:{title:"O caminho até a produção",prompt:"Ordene as etapas de uma esteira de entrega contínua.",lines:["A desenvolvedora envia o código (push)","O servidor de CI baixa o código e instala as dependências","Os testes automatizados são executados","O pacote da versão é gerado","A versão é publicada em produção"],hint:"Nada é empacotado antes de passar nos testes, e nada é publicado antes de ser empacotado.",why:"Cada etapa é um portão: só se empacota o que passou nos testes e só se publica o que foi empacotado de forma reprodutível.",analogy:"Linha de montagem: a peça chega, é montada, passa pelo controle de qualidade, é embalada e só então sai para a loja."},
o3:{title:"\"Na minha máquina funciona\"",prompt:"O aplicativo roda no notebook da Bia e quebra no servidor. Qual é a causa mais provável e a correção adequada?",opts:["Ambientes diferentes; declarar dependências e versões em arquivo e usar o mesmo ambiente em todo lugar","Servidor com defeito; comprar outro","Azar; tentar de novo amanhã","Linguagem ruim; reescrever em outra"],hint:"O código é o mesmo nos dois lugares. O que muda ao redor dele?",why:"O mesmo código se comporta de forma diferente quando versões e configurações mudam. Dependências declaradas e ambientes padronizados tornam a execução reprodutível.",analogy:"A receita dá certo na sua cozinha e falha na do vizinho porque o forno dele marca outra temperatura. Padronize o forno, não culpe o bolo."},
o4:{title:"Risco de publicação",prompt:"Classifique cada prática quanto ao risco de publicar.",bins:["Reduz o risco","Aumenta o risco"],cards:["Publicar mudanças pequenas várias vezes por semana","Acumular três meses de mudanças numa única publicação","Ter um comando de rollback já testado","Alterar arquivos direto no servidor de produção"],hint:"Pergunte: se der errado, será fácil descobrir a causa e voltar atrás?",why:"Mudança pequena tem causa fácil de achar, e rollback testado dá volta rápida. Publicação gigante e edição manual em produção tornam o erro difícil de localizar e de desfazer.",analogy:"Atravessar o rio pedra por pedra permite recuar um passo. Pular de uma margem à outra é tudo ou nada."},
o5:{title:"A CI está vermelha há três dias",prompt:"Um teste falha na CI há três dias e o time continua enviando código. Qual é a conduta correta?",opts:["Parar e consertar o build primeiro: alarme ignorado deixa de proteger","Desativar o teste que falha","Continuar e consertar tudo no fim do mês","Remover a CI, que só atrapalha"],hint:"Para que serve um alarme que todos aprenderam a ignorar?",why:"Com o build vermelho, novos defeitos entram escondidos atrás do primeiro. Consertar o build vira prioridade do time inteiro; desativar o teste apenas apaga a luz do painel.",analogy:"É a luz do óleo acesa no painel: colar fita isolante por cima não conserta o motor."}
});
LANG.pt.ui.rom="Mostrar o texto romanizado (alfabeto latino)";

