 models:{elo:"Elo/Rasch",irt:"TRI 3PL com EAP",bkt:"BKT",pfa:"PFA",afm:"AFM"}, rolePilot:"decide", roleShadow:"observa",
 cmpH:"Comparação dos modelos neste histórico",
